// ===== Modes Wrapper =====

struct mavsdk_modes_wrapper {
    std::shared_ptr<mavsdk::Modes> cpp_plugin;
};

mavsdk_modes_t
mavsdk_modes_create(mavsdk_system_t system) {
    if (system == nullptr) {
        return nullptr;
    }

    auto wrapper = new mavsdk_modes_wrapper();
    auto system_ptr = reinterpret_cast<std::shared_ptr<mavsdk::System>*>(system);
    wrapper->cpp_plugin = std::make_shared<mavsdk::Modes>(*system_ptr);

    return reinterpret_cast<mavsdk_modes_t>(wrapper);
}

void mavsdk_modes_destroy(mavsdk_modes_t modes) {
    if (modes == nullptr) {
        return;
    }

    // Releasing the handles is the caller's job. Dropping the plugin marks every
    // subscription of it dead anyway, so nothing can fire into it after this.
    delete reinterpret_cast<mavsdk_modes_wrapper*>(modes);
}

// ===== Method Implementations =====

// AvailableModes async
mavsdk_modes_available_modes_handle_t mavsdk_modes_subscribe_available_modes(
    mavsdk_modes_t modes,
    mavsdk_modes_available_modes_callback_t callback,
    void* user_data)
{
    auto wrapper = reinterpret_cast<mavsdk_modes_wrapper*>(modes);

    auto cpp_handle =    wrapper->cpp_plugin->subscribe_available_modes(
        [callback, user_data](
            std::vector<mavsdk::Modes::Mode> value) {
                if (callback) {
                    size_t count = value.size();
                    mavsdk_modes_mode_t* modes = nullptr;

                    if (count > 0) {
                        modes = new mavsdk_modes_mode_t[count];
                        for (size_t i = 0; i < count; i++) {
                            modes[i] = translate_mode_to_c(value[i]);
                        }
                    }

                    callback(
                        modes,
                        count,
                        user_data);
                }
        });

    auto cpp_handle_ptr = new mavsdk::Modes::AvailableModesHandle(std::move(cpp_handle));

    return reinterpret_cast<mavsdk_modes_available_modes_handle_t>(cpp_handle_ptr);
}

void mavsdk_modes_unsubscribe_available_modes(
    mavsdk_modes_t modes,
    mavsdk_modes_available_modes_handle_t handle)
{
    if (modes == nullptr || handle == nullptr) {
        return;
    }

    auto wrapper = reinterpret_cast<mavsdk_modes_wrapper*>(modes);
    auto cpp_handle = reinterpret_cast<mavsdk::Modes::AvailableModesHandle*>(handle);

    wrapper->cpp_plugin->unsubscribe_available_modes(std::move(*cpp_handle));
    delete cpp_handle;
}

// AvailableModes sync
void
mavsdk_modes_available_modes(
    mavsdk_modes_t modes,
    mavsdk_modes_mode_t** modes_out,
    size_t* modes_size_out)
{
    auto wrapper = reinterpret_cast<mavsdk_modes_wrapper*>(modes);

    auto ret_value = wrapper->cpp_plugin->available_modes();

    if (modes_out != nullptr) {
        *modes_out = translate__to_c(ret_value);
    }
}

// CurrentMode async
mavsdk_modes_current_mode_handle_t mavsdk_modes_subscribe_current_mode(
    mavsdk_modes_t modes,
    mavsdk_modes_current_mode_callback_t callback,
    void* user_data)
{
    auto wrapper = reinterpret_cast<mavsdk_modes_wrapper*>(modes);

    auto cpp_handle =    wrapper->cpp_plugin->subscribe_current_mode(
        [callback, user_data](
            mavsdk::Modes::Mode value) {
                if (callback) {
                    callback(
                        translate_mode_to_c(value),
                        user_data);
                }
        });

    auto cpp_handle_ptr = new mavsdk::Modes::CurrentModeHandle(std::move(cpp_handle));

    return reinterpret_cast<mavsdk_modes_current_mode_handle_t>(cpp_handle_ptr);
}

void mavsdk_modes_unsubscribe_current_mode(
    mavsdk_modes_t modes,
    mavsdk_modes_current_mode_handle_t handle)
{
    if (modes == nullptr || handle == nullptr) {
        return;
    }

    auto wrapper = reinterpret_cast<mavsdk_modes_wrapper*>(modes);
    auto cpp_handle = reinterpret_cast<mavsdk::Modes::CurrentModeHandle*>(handle);

    wrapper->cpp_plugin->unsubscribe_current_mode(std::move(*cpp_handle));
    delete cpp_handle;
}

// CurrentMode sync
void
mavsdk_modes_current_mode(
    mavsdk_modes_t modes,
    mavsdk_modes_mode_t* mode_out)
{
    auto wrapper = reinterpret_cast<mavsdk_modes_wrapper*>(modes);

    auto ret_value = wrapper->cpp_plugin->current_mode();

    if (mode_out != nullptr) {
        *mode_out = translate_mode_to_c(ret_value);
    }
}

// SetMode async
void mavsdk_modes_set_mode_async(
    mavsdk_modes_t modes,
    char* name,
    mavsdk_modes_set_mode_callback_t callback,
    void* user_data)
{
    auto wrapper = reinterpret_cast<mavsdk_modes_wrapper*>(modes);

    wrapper->cpp_plugin->set_mode_async(
        name,
        [callback, user_data](
            mavsdk::Modes::Result result) {
                if (callback) {
                    callback(
                        translate_result(result),
                        user_data);
                }
        });
}


// SetMode sync
mavsdk_modes_result_t
mavsdk_modes_set_mode(
    mavsdk_modes_t modes,
    char* name)
{
    auto wrapper = reinterpret_cast<mavsdk_modes_wrapper*>(modes);

    auto ret_value = wrapper->cpp_plugin->set_mode(        name);

    return translate_result(ret_value);
}
